CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE role (id SMALLINT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE accuracy_class (id SMALLINT PRIMARY KEY, symbol VARCHAR(10) NOT NULL UNIQUE, label VARCHAR(50) NOT NULL, min_n INTEGER NOT NULL, max_n INTEGER, description TEXT, CHECK (min_n > 0 AND (max_n IS NULL OR max_n >= min_n)));
CREATE TABLE rule_version (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_document VARCHAR(255) NOT NULL, effective_from DATE NOT NULL, effective_to DATE, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(effective_to IS NULL OR effective_to >= effective_from));
CREATE TABLE mpe_rule (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rule_version_id UUID NOT NULL REFERENCES rule_version(id), accuracy_class_id SMALLINT NOT NULL REFERENCES accuracy_class(id), load_band_min_e NUMERIC(14,4) NOT NULL, load_band_max_e NUMERIC(14,4), mpe_initial_e NUMERIC(6,3) NOT NULL, mpe_in_service_e NUMERIC(6,3) NOT NULL, CHECK(load_band_min_e >= 0), CHECK(load_band_max_e IS NULL OR load_band_max_e > load_band_min_e), CHECK(mpe_initial_e > 0 AND mpe_in_service_e > 0));
CREATE TABLE manufacturer (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), legal_name VARCHAR(255) NOT NULL, registration_no VARCHAR(100) UNIQUE, address TEXT, country VARCHAR(100), contact_email VARCHAR(255), contact_phone VARCHAR(50), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app_user (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE user_role (user_id UUID NOT NULL REFERENCES app_user(id), role_id SMALLINT NOT NULL REFERENCES role(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE instrument (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), manufacturer_id UUID NOT NULL REFERENCES manufacturer(id), model_no VARCHAR(150) NOT NULL, serial_no VARCHAR(150) NOT NULL, accuracy_class_id SMALLINT NOT NULL REFERENCES accuracy_class(id), max_capacity NUMERIC(14,4) NOT NULL, min_capacity NUMERIC(14,4) NOT NULL, e_value NUMERIC(14,6) NOT NULL, d_value NUMERIC(14,6) NOT NULL, n_intervals INTEGER GENERATED ALWAYS AS (FLOOR(max_capacity / NULLIF(e_value,0))) STORED, unit VARCHAR(10) NOT NULL DEFAULT 'kg', status VARCHAR(30) NOT NULL DEFAULT 'REGISTERED', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(d_value > 0 AND d_value <= e_value), CHECK(min_capacity >= 0 AND min_capacity < max_capacity), UNIQUE(manufacturer_id,serial_no));
CREATE TABLE test_session (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), instrument_id UUID NOT NULL REFERENCES instrument(id), engineer_id UUID NOT NULL REFERENCES app_user(id), reviewer_id UUID REFERENCES app_user(id), test_type VARCHAR(30) NOT NULL, rule_version_id UUID NOT NULL REFERENCES rule_version(id), status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', test_location TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(status IN ('DRAFT','SUBMITTED','REVIEWED','APPROVED','REJECTED')));
CREATE TABLE observation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), test_session_id UUID NOT NULL REFERENCES test_session(id), sequence_no INTEGER NOT NULL, test_procedure VARCHAR(50) NOT NULL, applied_load NUMERIC(14,4) NOT NULL, indicated_value NUMERIC(14,4) NOT NULL, load_position VARCHAR(20), recorded_by UUID NOT NULL REFERENCES app_user(id), recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), is_locked BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(test_session_id,sequence_no));
CREATE TABLE calculation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), observation_id UUID NOT NULL UNIQUE REFERENCES observation(id), error_value NUMERIC(14,6) NOT NULL, error_in_e NUMERIC(14,6) NOT NULL, applicable_mpe_id UUID NOT NULL REFERENCES mpe_rule(id), mpe_value NUMERIC(14,6) NOT NULL, within_tolerance BOOLEAN NOT NULL, engine_version VARCHAR(30) NOT NULL, computed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE compliance_result (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), test_session_id UUID NOT NULL REFERENCES test_session(id), scope VARCHAR(20) NOT NULL, observation_id UUID REFERENCES observation(id), verdict VARCHAR(10) NOT NULL, failure_reason TEXT, generated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(scope IN ('TEST_LEVEL','OBSERVATION_LEVEL')), CHECK(verdict IN ('PASS','FAIL')), CHECK((scope='TEST_LEVEL' AND observation_id IS NULL) OR (scope='OBSERVATION_LEVEL' AND observation_id IS NOT NULL)));
CREATE TABLE report (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), test_session_id UUID NOT NULL UNIQUE REFERENCES test_session(id), report_no VARCHAR(100) NOT NULL UNIQUE, pdf_object_key VARCHAR(500), docx_object_key VARCHAR(500), generated_by UUID NOT NULL REFERENCES app_user(id), generated_at TIMESTAMPTZ NOT NULL DEFAULT now(), is_final BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE hash_chain_entry (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), report_id UUID NOT NULL UNIQUE REFERENCES report(id), content_hash CHAR(64) NOT NULL, prev_hash CHAR(64), qr_token VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_log (id BIGSERIAL PRIMARY KEY, actor_user_id UUID REFERENCES app_user(id), entity_type VARCHAR(50) NOT NULL, entity_id UUID NOT NULL, action VARCHAR(30) NOT NULL, diff_json JSONB, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE regulatory_document (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rule_version_id UUID REFERENCES rule_version(id), source_title VARCHAR(255) NOT NULL, object_key VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE regulatory_embedding (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL REFERENCES regulatory_document(id), section_no VARCHAR(100), page_no INTEGER, char_offset INTEGER, content TEXT NOT NULL, embedding vector(384));
CREATE INDEX idx_mpe_lookup ON mpe_rule(rule_version_id,accuracy_class_id,load_band_min_e); CREATE INDEX idx_hash_qr ON hash_chain_entry(qr_token);
